package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.BagEstimate;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceGuarantee;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceIntervalKind;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceStateRef;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceStateSummary;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceZeroStatus;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.FrontierLayout;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.FrontierStateArena;
import org.eclipse.rdf4j.sail.lmdb.estimation.QuadSnapshotIdentity;
import org.junit.jupiter.api.Test;

class EstimateContextFrontierTest {

	private static final QuadSnapshotIdentity SNAPSHOT = new QuadSnapshotIdentity(1L, 2L, 3L);

	@Test
	void estimatedZeroPrefixDoesNotShortCircuitAsExactEmpty() {
		try (FrontierStateArena arena = new FrontierStateArena(64 * 1024L)) {
			EvidenceStateSummary sampledZero = new EvidenceStateSummary(
					0.0d,
					0.0d,
					10.0d,
					0.95d,
					EvidenceIntervalKind.POINTWISE,
					1.0d,
					2.0d,
					3.0d,
					0.0d,
					0.0d,
					10.0d,
					EvidenceGuarantee.MEASURE_UNBIASED,
					EvidenceZeroStatus.ESTIMATED_ZERO,
					"");
			EvidenceStateRef state = arena.append(FrontierLayout.of("x"), sampledZero);
			BagEstimate prefix = BagEstimate.heuristic(0.0d, "sampled-zero").withEvidenceState(state);
			EstimateContext context = EstimateContext.root(new SingletonSet(), SNAPSHOT, 3L)
					.withPrefixEstimate(prefix);

			assertFalse(context.hasNoExecutions());
		}
	}

	@Test
	void databaseExactZeroStillShortCircuits() {
		try (FrontierStateArena arena = new FrontierStateArena(64 * 1024L)) {
			EvidenceStateRef state = arena.append(FrontierLayout.empty(), EvidenceStateSummary.exact(0.0d));
			BagEstimate prefix = BagEstimate.exact(0.0d, "exact-zero").withEvidenceState(state);
			EstimateContext context = EstimateContext.root(new SingletonSet(), SNAPSHOT, 3L)
					.withPrefixEstimate(prefix);

			assertTrue(context.hasNoExecutions());
		}
	}

	@Test
	void stateLessScalarZeroDoesNotClaimExactEmptiness() {
		EstimateContext exactScalar = EstimateContext.root(new SingletonSet(), SNAPSHOT, 3L)
				.withPrefixEstimate(BagEstimate.exact(0.0d, "legacy-exact-zero"));
		EstimateContext heuristicScalar = EstimateContext.root(new SingletonSet(), SNAPSHOT, 3L)
				.withPrefixEstimate(BagEstimate.heuristic(0.0d, "heuristic-zero"));

		assertFalse(exactScalar.hasNoExecutions());
		assertFalse(heuristicScalar.hasNoExecutions());
	}
}
